from pathlib import Path
import re

MAIN=Path('web/src/main.js')
CSS=Path('web/src/styles.css')
PKG=Path('web/package.json')
s=MAIN.read_text(encoding='utf-8')

# Hidden hash route: intentionally unlinked from the public UI. This is obscurity, not authentication.
anchor="import './styles.css';\n\n"
insert="import './styles.css';\n\nconst ADMIN_HASH='#/_fm/control-room-30', WEB_VERSION='1.4.0';\n\n"
if anchor not in s:
    raise SystemExit('import anchor missing')
s=s.replace(anchor,insert,1)

old="games:[],gameDetails:new Map,gameMarkets:new Map,gameOpen:new Set,tradeA:null"
new="games:[],gameDetails:new Map,gameMarkets:new Map,gameOpen:new Set,adminTab:'overview',adminInspect:null,adminManifest:{},adminLoadedAt:0,tradeA:null"
if old not in s:
    raise SystemExit('state anchor missing')
s=s.replace(old,new,1)

old="async function snapshot(){st.snapshot=await json('/data/model_snapshot.json',{})||{};buildModelIndex(st.snapshot)}"
new="async function snapshot(force=false){const loader=force?liveJson:json;st.snapshot=await loader('/data/model_snapshot.json',{})||{};buildModelIndex(st.snapshot)}"
if old not in s:
    raise SystemExit('snapshot anchor missing')
s=s.replace(old,new,1)

about_pat=r"function about\(\)\{.*?\}\nfunction render\(\)"
m=re.search(about_pat,s,flags=re.S)
if not m:
    raise SystemExit('about/render anchor missing')
old_block=m.group(0)
about_only=old_block.rsplit('\nfunction render()',1)[0]
admin_code=r'''
function isAdminLocation(){return location.hash===ADMIN_HASH}
function adminMeta(){return st.snapshot?.metadata||st.snapshot?.meta||{}}
function adminModelVersion(){const m=adminMeta();return m.version||m.model_version||st.snapshot?.version||st.snapshot?.model_version||'Production snapshot'}
function adminPrimitiveRows(obj,limit=18){if(!obj||typeof obj!=='object')return'';return Object.entries(obj).filter(([,v])=>v==null||['string','number','boolean'].includes(typeof v)).slice(0,limit).map(([k,v])=>`<div class="admin-kv"><span>${esc(k)}</span><strong>${esc(v==null?'—':v)}</strong></div>`).join('')}
async function loadAdminManifest(force=true){st.adminManifest=(force?await liveJson('/data/snapshot_version.json',{}):await json('/data/snapshot_version.json',{}))||{};return st.adminManifest}
async function adminLoad(force=false){await Promise.all([players(force),loadSeasonStats(force),loadAdminManifest(true)]);st.adminLoadedAt=Date.now()}
function adminCoverage(){const keys=['live_projection','current_projection','projected_points','projection','proj_fpts','fpts_proj','pred','prediction','mean','weekly_projection'],skill=new Set(['QB','RB','WR','TE']),missing=[],unmatched=[];let total=0,projected=0;for(const base of st.rows||[]){const pos=String(field(base,['position'])||'').toUpperCase();if(!skill.has(pos))continue;total++;const id=field(base,['sleeper_id','sleeper_player_id','player_id']),name=field(base,['player_name','full_name','name'])||String(id||'Unknown'),weeks=Array.isArray(base.weekly_projections)?base.weekly_projections:[],w=weeks.find(x=>+field(x,['week','game_week','target_week'])===+st.week),current=+st.snapshot?.projection_week===+st.week,v=n(field(w,keys)??(current?field(base,keys):null));if(v!=null)projected++;else missing.push({name,pos,id});if(id!=null&&st.players&&Object.keys(st.players).length&&!st.players[String(id)])unmatched.push({name,pos,id})}return{total,projected,missing,unmatched}}
function adminUnavailable(){if(!st.players)return[];const hard=/(^|\b)(ir|out|pup|nfi|sus|inactive)($|\b)|injured reserve|physically unable|non.?football injury|suspended/i;return Object.entries(st.players).filter(([,p])=>hard.test(String(p?.status||''))||hard.test(String(p?.injury_status||''))).map(([id,p])=>({id,name:p.full_name||[p.first_name,p.last_name].filter(Boolean).join(' ')||id,pos:p.position,team:p.team,status:p.injury_status||p.status||'Unavailable'}))}
function adminCard(label,value,sub=''){return`<div class="admin-metric"><span>${esc(label)}</span><strong>${esc(value??'—')}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div>`}
function adminOverview(){const cov=adminCoverage(),manifest=st.adminManifest||{},loaded=st.adminLoadedAt?new Date(st.adminLoadedAt).toLocaleTimeString():'—';return`<div class="admin-grid admin-grid-4">${adminCard('Web version',WEB_VERSION,'Hidden console')}${adminCard('Model version',adminModelVersion())}${adminCard('Projection week',st.snapshot?.projection_week??st.week)}${adminCard('NFL week',st.nflWeek??'—')}${adminCard('Model players',fi(st.rows.length))}${adminCard('Week coverage',cov.total?`${cov.projected}/${cov.total}`:'—','QB/RB/WR/TE')}${adminCard('Sleeper directory',st.players?fi(Object.keys(st.players).length):'—')}${adminCard('Season-stat rows',fi(st.seasonStats.size),'Current regular season')}</div><div class="admin-split"><section class="admin-panel"><div class="admin-panel-title">Snapshot manifest</div>${adminPrimitiveRows(manifest)||'<p class="muted">No manifest fields are currently exposed.</p>'}</section><section class="admin-panel"><div class="admin-panel-title">Runtime</div>${adminPrimitiveRows(adminMeta())||'<p class="muted">No primitive metadata fields are currently exposed.</p>'}<div class="admin-kv"><span>Admin data loaded</span><strong>${esc(loaded)}</strong></div></section></div><div class="admin-warning"><strong>Hidden route, not authentication.</strong><span>This console is intentionally absent from navigation and normal routing, but anyone who inspects the shipped JavaScript could discover it. Sensitive write operations are therefore not exposed here.</span></div>`}
function adminHealth(){const cov=adminCoverage(),unavail=adminUnavailable(),miss=cov.missing.slice(0,30),unmatched=cov.unmatched.slice(0,30),pct=cov.total?100*cov.projected/cov.total:0;return`<div class="admin-grid admin-grid-4">${adminCard('Projection coverage',cov.total?`${f(pct,1)}%`:'—',`${cov.projected} of ${cov.total}`)}${adminCard('Missing week rows',fi(cov.missing.length),`Week ${st.week}`)}${adminCard('ID mismatches',fi(cov.unmatched.length),'Snapshot ID absent from Sleeper')}${adminCard('Definitive unavailable',fi(unavail.length),'Sleeper IR/Out/PUP/NFI/SUS/Inactive')}</div><div class="admin-split"><section class="admin-panel"><div class="admin-panel-title">Missing Week ${st.week} projections</div>${miss.length?`<div class="admin-list">${miss.map(x=>`<div><strong>${esc(x.name)}</strong><span>${esc(x.pos||'')} · ${esc(x.id||'no ID')}</span></div>`).join('')}</div>`:'<p class="admin-good">No missing skill-player projections detected.</p>'}${cov.missing.length>miss.length?`<p class="muted small">Showing first ${miss.length} of ${cov.missing.length}.</p>`:''}</section><section class="admin-panel"><div class="admin-panel-title">Identity mismatches</div>${unmatched.length?`<div class="admin-list">${unmatched.map(x=>`<div><strong>${esc(x.name)}</strong><span>${esc(x.pos||'')} · ${esc(x.id||'')}</span></div>`).join('')}</div>`:'<p class="admin-good">No snapshot-to-Sleeper ID mismatches detected for rows with IDs.</p>'}</section></div><section class="admin-panel" style="margin-top:14px"><div class="admin-panel-title">Definitive availability states</div>${unavail.length?`<div class="admin-list admin-list-3">${unavail.slice(0,40).map(x=>`<div><strong>${esc(x.name)}</strong><span>${esc(x.pos||'')} · ${esc(x.team||'FA')} · ${esc(x.status)}</span></div>`).join('')}</div>`:'<p class="muted">No definitive unavailable players detected in the loaded Sleeper directory.</p>'}</section>`}
function adminInspector(){const id=st.adminInspect;if(!id)return'<div class="empty">Search for a player above to inspect the exact production projection path.</div>';const p=st.players?.[id]||{},m=model(id,p),entry=resolveModel(id,p),base=entry?.base||null,w=entry?.weeks?.get(+st.week)||null,av=m.availability||{},rows=[['Final projection',f(m.projection)],['Raw projection',f(m.rawProjection)],['Pregame projection',f(m.pregame)],['Floor',f(m.floor)],['Ceiling',f(m.ceiling)],['Season PPG',f(m.avg)],['Dynasty value',m.dynasty!=null?fi(m.dynasty):'—'],['Confidence',conf(m.confidence)],['Opponent',m.opp||'—'],['Availability',`${Math.round((m.availabilityFactor??1)*100)}%`],['Matched model row',m.matched?'Yes':'No'],[`Week ${st.week} row`,m.hasWeek?'Yes':'No']];return`<section class="admin-panel"><div class="admin-inspect-head"><div class="admin-player"><img src="${assetImage(id,p)}" alt="" onerror="this.style.display='none'"><div><div class="eyebrow">Projection diagnostic</div><h2>${esc(pname(id))}</h2><span>${esc(p.position||'')} · ${esc(p.team||'FA')} · Sleeper ${esc(id)}</span></div></div>${availabilityChip(av)}</div><div class="admin-grid admin-grid-4">${rows.map(([a,b])=>adminCard(a,b)).join('')}</div><div class="admin-split" style="margin-top:14px"><div class="admin-panel inset"><div class="admin-panel-title">Availability reasoning</div><p>${esc(av.reason||'No availability restriction detected.')}</p><div class="admin-kv"><span>Status</span><strong>${esc(av.injuryStatus||av.rosterStatus||'Available')}</strong></div><div class="admin-kv"><span>Body part</span><strong>${esc(av.body||'—')}</strong></div><div class="admin-kv"><span>Notes</span><strong>${esc(av.notes||'—')}</strong></div></div><div class="admin-panel inset"><div class="admin-panel-title">Base model row</div><pre class="admin-json">${esc(JSON.stringify(base,null,2))}</pre></div></div><div class="admin-panel inset" style="margin-top:14px"><div class="admin-panel-title">Selected weekly row · Week ${st.week}</div><pre class="admin-json">${esc(JSON.stringify(w,null,2))}</pre></div></section>`}
function adminProjections(){return`<div class="admin-toolbar"><div><h2>Projection Lab</h2><p class="muted">Inspect raw snapshot data, availability overrides and the final value used by the website.</p></div>${weekSel()}</div><div class="admin-panel"><input id="admin-player-search" class="input" placeholder="Search QB, RB, WR or TE…" autocomplete="off"><div id="admin-player-results" class="asset-list" style="margin-top:9px"></div></div><div style="margin-top:14px">${adminInspector()}</div>`}
function adminAccuracyData(){const s=st.snapshot||{},m=adminMeta();return s.accuracy||s.performance||s.validation||s.metrics||m.accuracy||m.performance||null}
function adminAccuracy(){const x=adminAccuracyData();return`<section class="admin-panel"><div class="admin-panel-title">Accuracy / validation payload</div>${x?`<p class="muted small">Displayed exactly as exported by the current production web snapshot; this console does not invent missing accuracy metrics.</p><pre class="admin-json tall">${esc(JSON.stringify(x,null,2))}</pre>`:'<div class="empty">The current web snapshot does not export an accuracy/performance object. Historical validation still lives in the model outputs/repository, but it is not silently substituted here.</div>'}</section>`}
function adminTools(){const keys=Object.keys(localStorage).sort();return`<div class="admin-grid admin-grid-3"><button class="admin-action" data-a="adminRefresh"><strong>Refresh admin data</strong><span>Bypass browser cache for snapshot manifest, Sleeper player directory and season stats.</span></button><button class="admin-action" data-a="adminClearCache"><strong>Clear app caches</strong><span>Clear Fantasy Model player/browser Cache API data, then reload fresh admin data.</span></button><button class="admin-action" data-a="adminReload"><strong>Reload application</strong><span>Perform a full page reload at this hidden route.</span></button></div><div class="admin-split" style="margin-top:14px"><section class="admin-panel"><div class="admin-panel-title">Local storage keys</div>${keys.length?`<div class="admin-list">${keys.map(k=>`<div><strong>${esc(k)}</strong><span>Value hidden</span></div>`).join('')}</div>`:'<p class="muted">No localStorage keys.</p>'}</section><section class="admin-panel"><div class="admin-panel-title">Production controls</div><p>This browser console intentionally does <strong>not</strong> contain GitHub tokens or a public endpoint capable of launching production workflows. Model rebuild/force-refresh actions remain protected in GitHub Actions until an authenticated backend is added.</p></section></div>`}
function adminTabs(){const tabs=[['overview','Overview'],['health','Data Health'],['projections','Projection Lab'],['accuracy','Accuracy'],['tools','Browser Tools']];return`<nav class="admin-tabs">${tabs.map(([k,v])=>`<button class="${st.adminTab===k?'active':''}" data-admin-tab="${k}">${v}</button>`).join('')}</nav>`}
function admin(){const body=st.adminTab==='health'?adminHealth():st.adminTab==='projections'?adminProjections():st.adminTab==='accuracy'?adminAccuracy():st.adminTab==='tools'?adminTools():adminOverview();return`<div class="admin-shell"><header class="admin-topbar"><div><div class="eyebrow">Fantasy Model · private operations surface</div><h1>Control Room</h1><p>Web ${WEB_VERSION} · ${esc(adminModelVersion())}</p></div><div class="admin-top-actions"><span class="admin-route-badge">UNLINKED ROUTE</span><button class="btn btn-ghost" data-a="exitAdmin">Exit</button></div></header>${adminTabs()}<main class="admin-content">${body}</main></div>`}
async function adminRefresh(){await Promise.all([snapshot(true),nflState(),players(true),loadSeasonStats(true),loadAdminManifest(true)]);st.adminLoadedAt=Date.now();render();toast('Admin data refreshed from production sources.')}
async function adminClearCache(){try{localStorage.removeItem('fm_players_cache');localStorage.removeItem('fm_players_cache_at');if('caches'in window){const names=await caches.keys();await Promise.all(names.map(k=>caches.delete(k)))}}catch(e){console.warn('cache clear',e)}st.players=null;st.seasonStats=new Map;st.seasonStatsAt=0;await adminRefresh();toast('Fantasy Model browser caches cleared.')}
function bindAdmin(){$$('[data-admin-tab]').forEach(x=>x.onclick=()=>{st.adminTab=x.dataset.adminTab;render()});$('[data-a="adminRefresh"]')?.addEventListener('click',adminRefresh);$('[data-a="adminClearCache"]')?.addEventListener('click',adminClearCache);$('[data-a="adminReload"]')?.addEventListener('click',()=>location.reload());$('[data-a="exitAdmin"]')?.addEventListener('click',()=>{history.replaceState(null,'',location.pathname+location.search);location.reload()});const q=$('#admin-player-search'),box=$('#admin-player-results');if(q&&box)q.oninput=()=>{const needle=normName(q.value),found=!needle||!st.players?[]:Object.entries(st.players).filter(([,p])=>['QB','RB','WR','TE'].includes(String(p?.position||'').toUpperCase())&&normName(p?.full_name||[p?.first_name,p?.last_name].filter(Boolean).join(' ')).includes(needle)).slice(0,15);box.innerHTML=found.map(([id,p])=>`<button class="asset" data-admin-inspect="${esc(id)}"><span><strong>${esc(p.full_name||pname(id))}</strong><span class="muted small" style="display:block">${esc(p.position||'')} · ${esc(p.team||'FA')}</span></span><span>Inspect</span></button>`).join('');$$('[data-admin-inspect]',box).forEach(x=>x.onclick=()=>{st.adminInspect=x.dataset.adminInspect;render()})}}
'''
new_block=about_only+'\n'+admin_code+'\nfunction render()'
s=s[:m.start()]+new_block+s[m.end():]

old="function render(){const html=st.route==='dashboard'?dashboard():st.route==='live'?live():st.route==='leaders'?leaders():st.route==='startsit'?startsit():about();$('#app').innerHTML=html;bind()}"
new="function render(){const html=isAdminLocation()?admin():st.route==='dashboard'?dashboard():st.route==='live'?live():st.route==='leaders'?leaders():st.route==='startsit'?startsit():about();$('#app').innerHTML=html;bind()}"
if old not in s:
    raise SystemExit('render exact anchor missing after injection')
s=s.replace(old,new,1)

if "function bind(){" not in s:
    raise SystemExit('bind anchor missing')
s=s.replace("function bind(){","function bind(){bindAdmin();",1)

old_init="async function init(){await Promise.all([snapshot(),nflState()]);render();if(st.username){await loadLeagues(st.username,st.season);const id=localStorage.fm_league_id;if(id&&st.leagues.some(l=>String(l.league_id)===id))await openLeague(id)}if(st.route==='live')liveLoad()}\ninit();"
new_init="async function init(){await Promise.all([snapshot(),nflState()]);if(isAdminLocation()){await adminLoad();render();return}render();if(st.username){await loadLeagues(st.username,st.season);const id=localStorage.fm_league_id;if(id&&st.leagues.some(l=>String(l.league_id)===id))await openLeague(id)}if(st.route==='live')liveLoad()}\nwindow.addEventListener('hashchange',async()=>{if(isAdminLocation()){await adminLoad();render()}else location.reload()});\ninit();"
if old_init not in s:
    raise SystemExit('init anchor missing')
s=s.replace(old_init,new_init,1)

MAIN.write_text(s,encoding='utf-8')

css=CSS.read_text(encoding='utf-8')
css += r'''

/* Web 1.4.0 — unlinked control room */
.admin-shell{min-height:100vh;background:radial-gradient(circle at 15% -10%,rgba(182,255,69,.08),transparent 28%),#080b09}.admin-topbar{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:22px clamp(18px,4vw,48px);border-bottom:1px solid var(--line);background:rgba(8,11,9,.92);position:sticky;top:0;z-index:20;backdrop-filter:blur(18px)}.admin-topbar h1{font-size:28px;margin:3px 0}.admin-topbar p{margin:0;color:var(--muted);font-size:12px}.admin-top-actions{display:flex;align-items:center;gap:10px}.admin-route-badge{font-size:9px;letter-spacing:.11em;color:var(--warn);border:1px solid rgba(255,209,102,.25);border-radius:999px;padding:6px 9px}.admin-tabs{display:flex;gap:6px;overflow:auto;padding:12px clamp(18px,4vw,48px) 0;border-bottom:1px solid var(--line);background:#0a0f0c;scrollbar-width:none}.admin-tabs button{border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);padding:11px 13px;cursor:pointer;font-weight:800;white-space:nowrap}.admin-tabs button.active{color:var(--accent);border-color:var(--accent)}.admin-content{padding:clamp(18px,4vw,48px);max-width:1500px;margin:auto}.admin-grid{display:grid;gap:10px}.admin-grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.admin-grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}.admin-metric{padding:14px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(180deg,rgba(18,26,22,.95),rgba(13,19,16,.95));min-width:0}.admin-metric>span,.admin-metric>small{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.07em}.admin-metric>strong{display:block;font-size:21px;margin:5px 0;overflow:hidden;text-overflow:ellipsis}.admin-metric>small{text-transform:none;letter-spacing:0}.admin-split{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.admin-panel{padding:17px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(180deg,rgba(18,26,22,.96),rgba(13,19,16,.96));min-width:0}.admin-panel.inset{background:rgba(255,255,255,.015)}.admin-panel-title{font-size:13px;font-weight:900;text-transform:uppercase;letter-spacing:.07em;margin-bottom:12px;color:#dce8df}.admin-kv{display:flex;justify-content:space-between;gap:16px;padding:8px 0;border-bottom:1px solid rgba(36,51,43,.65);font-size:12px}.admin-kv span{color:var(--muted)}.admin-kv strong{text-align:right;overflow-wrap:anywhere}.admin-warning{display:grid;gap:5px;margin-top:14px;padding:13px 15px;border:1px solid rgba(255,209,102,.24);background:rgba(255,209,102,.055);border-radius:12px}.admin-warning strong{color:var(--warn)}.admin-warning span{font-size:12px;color:#d7dfda;line-height:1.45}.admin-good{color:var(--good);font-size:12px}.admin-list{display:grid;gap:5px}.admin-list-3{grid-template-columns:repeat(3,minmax(0,1fr))}.admin-list>div{display:flex;justify-content:space-between;gap:10px;padding:8px 9px;border:1px solid rgba(36,51,43,.62);border-radius:8px;background:rgba(255,255,255,.012);min-width:0}.admin-list strong{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.admin-list span{font-size:10px;color:var(--muted);text-align:right}.admin-toolbar{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:14px}.admin-toolbar h2{margin:0 0 4px}.admin-toolbar p{margin:0}.admin-toolbar .select{width:auto;min-width:110px}.admin-inspect-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:15px}.admin-player{display:flex;align-items:center;gap:12px}.admin-player img{width:64px;height:64px;border-radius:13px;object-fit:cover;object-position:center 15%;background:#17211c}.admin-player h2{margin:2px 0 3px}.admin-player span{font-size:11px;color:var(--muted)}.admin-json{margin:0;max-height:340px;overflow:auto;padding:12px;border:1px solid rgba(36,51,43,.75);border-radius:9px;background:#080b09;color:#cfe0d5;font:11px/1.45 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.admin-json.tall{max-height:620px}.admin-action{display:grid;gap:7px;text-align:left;padding:17px;border:1px solid var(--line);border-radius:13px;background:var(--panel2);color:inherit;cursor:pointer}.admin-action:hover{border-color:rgba(182,255,69,.35)}.admin-action strong{font-size:15px}.admin-action span{font-size:11px;line-height:1.45;color:var(--muted)}@media(max-width:900px){.admin-grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-grid-3,.admin-split{grid-template-columns:1fr}.admin-list-3{grid-template-columns:1fr 1fr}}@media(max-width:600px){.admin-topbar{position:static;padding:16px 12px}.admin-topbar h1{font-size:23px}.admin-route-badge{display:none}.admin-tabs{padding-left:10px;padding-right:10px}.admin-content{padding:14px 12px}.admin-grid-4{grid-template-columns:1fr 1fr}.admin-list-3{grid-template-columns:1fr}.admin-toolbar{align-items:stretch;flex-direction:column}.admin-toolbar .select{width:100%}.admin-inspect-head{align-items:flex-start;flex-direction:column}}
'''
CSS.write_text(css,encoding='utf-8')

p=PKG.read_text(encoding='utf-8')
if '"version": "1.3.9"' not in p:
    raise SystemExit('expected Web 1.3.9')
p=p.replace('"version": "1.3.9"','"version": "1.4.0"',1)
PKG.write_text(p,encoding='utf-8')
print('Patched Web 1.4.0: hidden unlinked control room')
